CREATE FUNCTION "sb4_eval_g70"._sb4_guard_269f0c08459892ce6c7e5f8e() RETURNS pg_catalog.void LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog AS $sb4_check$BEGIN IF pg_catalog.current_setting('client_encoding') OPERATOR(pg_catalog.<>) 'UTF8' OR pg_catalog.current_setting('extra_float_digits') OPERATOR(pg_catalog.<>) '3' OR pg_catalog.current_setting('bytea_output') OPERATOR(pg_catalog.<>) 'hex' THEN RAISE EXCEPTION 'Postgres flight output settings drifted' USING ERRCODE = 'S4001'; END IF; END$sb4_check$;
CREATE FUNCTION "sb4_eval_g70"._sb4_fence_782bfaadebb1dde2d48f643f(pg_catalog.int8,pg_catalog.text) RETURNS pg_catalog.void LANGUAGE plpgsql VOLATILE PARALLEL UNSAFE SECURITY INVOKER SET search_path=pg_catalog AS $sb4_check$DECLARE current_store pg_catalog.text; current_token pg_catalog.int8; BEGIN SELECT store_id,token INTO current_store,current_token FROM "sb4_eval_g70"._owner WHERE singleton FOR KEY SHARE; IF NOT FOUND OR current_token IS NULL OR current_token OPERATOR(pg_catalog.<>) $1 OR ($2 IS NOT NULL AND (current_store IS NULL OR current_store OPERATOR(pg_catalog.<>) $2)) THEN RAISE EXCEPTION 'stale owner token or logical store identity' USING ERRCODE='S4002'; END IF; END$sb4_check$;
